import{_ as t,o as i,c as s,ag as o}from"./chunks/framework.DqVSm8kp.js";const l="/llmxray/docs/educators/fr/tool-calling-loop.svg",n="/llmxray/docs/educators/fr/tool-definition.svg",a="/llmxray/docs/educators/fr/tool-calling-failures.svg",q=JSON.parse(`{"title":"Module 6 : L'IA peut-elle utiliser des outils ?","description":"","frontmatter":{},"headers":[],"relativePath":"fr/community/educators/module-6.md","filePath":"fr/community/educators/module-6.md"}`),r={name:"fr/community/educators/module-6.md"};function u(d,e,c,p,m,h){return i(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="module-6-l-ia-peut-elle-utiliser-des-outils" tabindex="-1">Module 6 : L&#39;IA peut-elle utiliser des outils ? <a class="header-anchor" href="#module-6-l-ia-peut-elle-utiliser-des-outils" aria-label="Permalink to &quot;Module 6 : L&#39;IA peut-elle utiliser des outils ?&quot;">​</a></h1><div style="background:linear-gradient(135deg, rgba(168,85,247,0.08), rgba(124,58,237,0.04));border-left:4px solid #a855f7;padding:1rem 1.5rem;border-radius:0 8px 8px 0;margin-bottom:2rem;"><p><strong>L&#39;Ingénieur</strong> — Construisez des ponts entre le langage et l&#39;action</p><p><strong>Durée :</strong> 60 min | <strong>Difficulté :</strong> Intermédiaire | <strong>Prérequis :</strong> <a href="./module-1.html">Module 1</a>, <a href="./module-5.html">Module 5</a></p></div><h2 id="le-moment-eureka" tabindex="-1">Le Moment Eureka <a class="header-anchor" href="#le-moment-eureka" aria-label="Permalink to &quot;Le Moment Eureka&quot;">​</a></h2><blockquote><p>Le tool calling est de la correspondance de motifs, pas de la compréhension. Le modèle ne sait pas ce que fait une API — il fait correspondre votre requête à une signature de function et génère des arguments JSON. C&#39;est la même prédiction du prochain token, simplement orientée vers une sortie structurée.</p></blockquote><p>Quand un modèle &quot;utilise une calculatrice&quot; ou &quot;consulte la météo&quot;, cela ressemble à de l&#39;intelligence en action — un esprit qui reconnaît ses propres limites et cherche l&#39;instrument approprié. La réalité est bien plus mécanique. Le modèle reçoit des définitions d&#39;outils dans son prompt — des schemas JSON décrivant les noms de function, les types de paramètres et des descriptions en langage naturel. Lorsque votre requête correspond à l&#39;une de ces descriptions par correspondance de motifs, la prédiction du prochain token du modèle bascule de la génération de prose vers la génération d&#39;un objet JSON structuré <code>tool_call</code>. Il n&#39;a aucune notion de ce que fait la function, aucun modèle mental des requêtes HTTP ou des bases de données. Il remplit un gabarit.</p><p>Cette distinction est fondamentale. Comprendre que le tool calling est de la génération structurée — et non de l&#39;agentivité — permet aux étudiants de raisonner sur pourquoi les outils échouent parfois, pourquoi les descriptions doivent être précises, et pourquoi donner à un modèle l&#39;accès à un outil dangereux est fondamentalement un problème de conception de permissions, pas un problème d&#39;intelligence. Le modèle appellera n&#39;importe quel outil qui correspond le mieux au motif, indépendamment des conséquences.</p><hr><h2 id="contexte-conceptuel" tabindex="-1">Contexte Conceptuel <a class="header-anchor" href="#contexte-conceptuel" aria-label="Permalink to &quot;Contexte Conceptuel&quot;">​</a></h2><h3 id="qu-est-ce-que-le-tool-calling" tabindex="-1">Qu&#39;est-ce que le tool calling ? <a class="header-anchor" href="#qu-est-ce-que-le-tool-calling" aria-label="Permalink to &quot;Qu&#39;est-ce que le tool calling ?&quot;">​</a></h3><p>Lorsqu&#39;un modèle de langage génère une réponse, il produit normalement du langage naturel — des phrases, des paragraphes, des explications. Le <strong>tool calling</strong> est un mode dans lequel le modèle génère à la place un objet JSON structuré : un nom de function accompagné d&#39;un ensemble d&#39;arguments typés. Cet objet n&#39;est pas exécuté par le modèle. Il est renvoyé à l&#39;application, qui exécute la function réelle, collecte le résultat et le réinjecte dans la conversation pour que le modèle l&#39;intègre dans sa réponse finale.</p><p>Le modèle n&#39;exécute jamais rien lui-même. Il ne dispose d&#39;aucun runtime, d&#39;aucun interpréteur, d&#39;aucun accès au réseau ou au système de fichiers. C&#39;est un générateur de texte qui a été entraîné à produire un format JSON spécifique lorsque le contexte suggère qu&#39;un outil devrait être invoqué. La couche applicative — en l&#39;occurrence LLMxRay — est ce qui fait le pont entre la sortie structurée du modèle et l&#39;exécution dans le monde réel.</p><p>C&#39;est une frontière architecturale critique. Le modèle propose ; l&#39;application dispose. Chaque appel d&#39;outil passe par du code applicatif qui peut le valider, l&#39;isoler dans un bac à sable, le limiter en débit ou le rejeter avant exécution. Cette séparation est ce qui rend le tool calling sûr (lorsqu&#39;il est correctement conçu) ou dangereux (lorsque l&#39;application fait aveuglément confiance à la sortie du modèle).</p><h3 id="la-boucle-du-tool-calling" tabindex="-1">La boucle du tool calling <a class="header-anchor" href="#la-boucle-du-tool-calling" aria-label="Permalink to &quot;La boucle du tool calling&quot;">​</a></h3><p>Le cycle de vie complet d&#39;une conversation augmentée par des outils suit une boucle stricte :</p><ol><li><strong>Message de l&#39;utilisateur</strong> — Vous posez une question ou formulez une requête (&quot;What time is it in Tokyo?&quot;)</li><li><strong>Le modèle décide d&#39;appeler un outil</strong> — En se basant sur les définitions d&#39;outils dans son contexte, le modèle génère un objet <code>tool_call</code> au lieu d&#39;une réponse textuelle (par ex. <code>{&quot;name&quot;: &quot;current_time&quot;, &quot;arguments&quot;: {&quot;timezone&quot;: &quot;Asia/Tokyo&quot;}}</code>)</li><li><strong>L&#39;application exécute l&#39;outil</strong> — LLMxRay reçoit l&#39;appel d&#39;outil, exécute la function correspondante dans un environnement isolé et capture le résultat</li><li><strong>Le résultat est réinjecté</strong> — La sortie de l&#39;outil est ajoutée à la conversation sous forme d&#39;un message avec le rôle <code>tool</code></li><li><strong>Le modèle génère la réponse finale</strong> — Avec le résultat de l&#39;outil désormais dans le contexte, le modèle produit une réponse en langage naturel (&quot;The current time in Tokyo is 2:34 PM JST&quot;)</li></ol><p>Cette boucle peut se répéter. Si le modèle détermine qu&#39;il a besoin d&#39;informations supplémentaires après avoir vu le résultat du premier outil, il peut émettre un nouvel appel d&#39;outil. LLMxRay supporte jusqu&#39;à <strong>5 rounds d&#39;appels d&#39;outils par tour</strong>, permettant des chaînes de raisonnement en plusieurs étapes où la sortie de chaque outil guide l&#39;appel suivant.</p><p><img src="'+l+`" alt="La boucle du tool calling"></p><h3 id="comment-le-modele-decide-d-appeler-un-outil" tabindex="-1">Comment le modèle &quot;décide&quot; d&#39;appeler un outil <a class="header-anchor" href="#comment-le-modele-decide-d-appeler-un-outil" aria-label="Permalink to &quot;Comment le modèle &quot;décide&quot; d&#39;appeler un outil&quot;">​</a></h3><p>Il ne décide pas — il <strong>prédit</strong>. Cette distinction est le noyau conceptuel de ce module.</p><p>Lorsque le tool calling est activé, les définitions d&#39;outils sont injectées dans le prompt du modèle sous forme de schemas JSON — généralement dans le message système ou un bloc dédié aux outils. Ces définitions deviennent partie intégrante du contexte que le modèle lit avant de générer ses prochains tokens. Le modèle a été affiné (durant son entraînement) pour reconnaître quand la requête d&#39;un utilisateur s&#39;aligne avec l&#39;une des descriptions d&#39;outils disponibles et pour produire un objet <code>tool_call</code> dans ces cas.</p><p>C&#39;est pourquoi <strong>les bonnes descriptions sont essentielles</strong>. Le champ description dans une définition d&#39;outil est le seul guide dont dispose le modèle pour savoir ce que fait l&#39;outil. Le modèle ne peut pas inspecter le code source de l&#39;outil. Il ne peut pas le tester. Il lit la description — quelques phrases en langage naturel — et décide (prédit) si la requête actuelle correspond. Une description vague mène à des appels manqués ou erronés. Une description précise mène à une invocation fiable.</p><p>Considérez deux descriptions pour le même outil :</p><ul><li><strong>Bonne</strong> : &quot;Get the current weather conditions for a given city, returning temperature in Celsius and a short description&quot;</li><li><strong>Mauvaise</strong> : &quot;A utility function&quot;</li></ul><p>La première donne au modèle suffisamment de signal pour faire correspondre &quot;What&#39;s the weather in Lyon?&quot; à cet outil. La seconde ne lui donne presque rien — le modèle pourrait ignorer l&#39;outil entièrement, ou pire, l&#39;appeler pour des requêtes sans rapport parce qu&#39;il ne peut pas déterminer ce qu&#39;il fait.</p><h3 id="definitions-d-outils-le-contrat" tabindex="-1">Définitions d&#39;outils : le contrat <a class="header-anchor" href="#definitions-d-outils-le-contrat" aria-label="Permalink to &quot;Définitions d&#39;outils : le contrat&quot;">​</a></h3><p>Une définition d&#39;outil est un schema JSON qui sert de contrat entre le modèle et l&#39;application. Elle comporte trois parties essentielles :</p><ul><li><strong><code>name</code></strong> — Un identifiant unique pour la function (par ex. <code>weather_check</code>, <code>calculate</code>, <code>generate_uuid</code>). C&#39;est ce qui apparaît dans la sortie <code>tool_call</code> du modèle.</li><li><strong><code>description</code></strong> — Une explication en langage naturel de ce que fait l&#39;outil et quand l&#39;utiliser. C&#39;est le champ le plus important — c&#39;est ce que le modèle lit pour déterminer la pertinence.</li><li><strong><code>parameters</code></strong> — Un objet JSON Schema définissant les arguments que la function accepte, incluant leurs types (<code>string</code>, <code>number</code>, <code>boolean</code>, <code>array</code>, <code>object</code>), descriptions et lesquels sont <code>required</code>.</li></ul><p>Voici un exemple de définition d&#39;outil bien structurée :</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;function&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;function&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;weather_check&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;description&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Get the current weather conditions for a given city. Returns temperature in Celsius, humidity, and a short description of conditions.&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;parameters&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;object&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;properties&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;city&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">          &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;string&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">          &quot;description&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;The name of the city to check weather for&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;units&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">          &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;string&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">          &quot;enum&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;celsius&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;fahrenheit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">          &quot;description&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Temperature unit (default: celsius)&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;required&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;city&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Il s&#39;agit d&#39;un format compatible OpenAI, qui est le standard suivi par Ollama et LLMxRay. Le bloc <code>parameters</code> est lui-même un JSON Schema — le même format utilisé pour valider les formulaires web et les requêtes API dans toute l&#39;industrie logicielle. Les étudiants qui apprennent à lire les définitions d&#39;outils ici acquièrent une compétence transférable.</p><p><img src="`+n+'" alt="Anatomie d&#39;une définition d&#39;outil"></p><p>Dans le <strong>Tool Workshop</strong> de LLMxRay, vous pouvez voir ce schema rendu visuellement. L&#39;onglet <strong>Schema</strong> affiche le JSON Schema auto-généré pour tout outil que vous créez, et le <strong>Code Panel</strong> montre l&#39;implémentation exécutable avec synchronisation bidirectionnelle — modifiez le code et le schema se met à jour, modifiez le schema et le code suit.</p><h3 id="quand-le-tool-calling-echoue" tabindex="-1">Quand le tool calling échoue <a class="header-anchor" href="#quand-le-tool-calling-echoue" aria-label="Permalink to &quot;Quand le tool calling échoue&quot;">​</a></h3><p>Le tool calling peut échouer de plusieurs manières, et comprendre ces modes de défaillance est essentiel pour construire des systèmes fiables :</p><ul><li><strong>Mauvais outil sélectionné</strong> — Le modèle appelle <code>calculate</code> quand vous avez demandé l&#39;heure. Cela signifie généralement que les descriptions sont ambiguës ou se chevauchent. Si deux outils ont des descriptions similaires, le modèle peut faire correspondre le mauvais.</li><li><strong>Arguments hallucinés</strong> — Le modèle invente des valeurs de paramètres qui ne correspondent pas au schema. Par exemple, passer <code>{&quot;location&quot;: &quot;Paris&quot;}</code> quand le paramètre s&#39;appelle <code>city</code>. C&#39;est le même comportement d&#39;hallucination vu au Module 3, mais appliqué à la sortie structurée.</li><li><strong>Champs requis manquants</strong> — Le modèle génère un appel d&#39;outil mais omet un paramètre requis. L&#39;application devrait valider contre le schema et renvoyer une erreur, donnant au modèle une chance de réessayer.</li><li><strong>Le modèle ne supporte pas les outils</strong> — Tous les modèles ne peuvent pas faire du tool calling. Les modèles plus petits ou les architectures plus anciennes peuvent ne pas avoir été affinés pour la sortie structurée. Ils peuvent ignorer entièrement les définitions d&#39;outils ou produire du JSON malformé.</li><li><strong>L&#39;outil renvoie une erreur</strong> — La function s&#39;exécute mais échoue (timeout réseau, entrée invalide, limite de débit). Le modèle reçoit le message d&#39;erreur et doit décider comment procéder — réessayer, s&#39;excuser ou tenter une approche différente.</li></ul><p><img src="'+a+'" alt="Quand le tool calling échoue"></p><div class="warning custom-block"><p class="custom-block-title">Tous les modèles ne supportent pas le tool calling</p><p>LLMxRay détecte automatiquement si un modèle supporte le tool calling en vérifiant ses capacités lors du chargement du modèle. Si un modèle ne supporte pas les outils, les toggles d&#39;outils dans les Chat Settings seront désactivés. Les modèles plus petits (moins de 7B paramètres) manquent souvent de la capacité de tool calling. Vérifiez toujours le support avant de concevoir des exercices autour de modèles spécifiques.</p></div><hr><h2 id="exercices-pratiques" tabindex="-1">Exercices Pratiques <a class="header-anchor" href="#exercices-pratiques" aria-label="Permalink to &quot;Exercices Pratiques&quot;">​</a></h2><h3 id="exercice-1-votre-premier-outil" tabindex="-1">Exercice 1 : Votre premier outil <a class="header-anchor" href="#exercice-1-votre-premier-outil" aria-label="Permalink to &quot;Exercice 1 : Votre premier outil&quot;">​</a></h3><p><strong>Ce qu&#39;il faut faire :</strong></p><ol><li>Ouvrez le <strong>Tool Workshop</strong> dans LLMxRay</li><li>Parcourez les <strong>Tool Templates</strong> — sélectionnez <strong>&quot;Current Time&quot;</strong> parmi les modèles Utility</li><li>Examinez l&#39;outil sous trois vues : <ul><li>Le panneau de <strong>définition de l&#39;outil</strong> : notez le <code>name</code>, la <code>description</code> et les <code>parameters</code></li><li>Le <strong>Code Panel</strong> : lisez l&#39;implémentation JavaScript — c&#39;est ce qui s&#39;exécute réellement lorsque l&#39;outil est appelé</li><li>L&#39;onglet <strong>Schema</strong> : voyez le JSON Schema auto-généré qui est envoyé au modèle</li></ul></li><li>Remarquez le canevas visuel basé sur des nœuds — l&#39;outil apparaît comme un nœud connecté montrant les entrées, le traitement et les sorties</li><li>Allez maintenant dans <strong>Chat</strong> et ouvrez les <strong>Chat Settings</strong>. Trouvez les toggles d&#39;outils et activez &quot;Current Time&quot;</li><li>Demandez au modèle : <em>&quot;What time is it?&quot;</em></li><li>Observez la réponse — le modèle devrait générer un <code>tool_call</code> au lieu de deviner l&#39;heure</li><li>Naviguez vers la page <strong>Session</strong> et ouvrez l&#39;onglet <strong>Tools</strong>. Trouvez l&#39;appel d&#39;outil dans le <strong>ToolCallTimeline</strong> et examinez-le</li></ol><p><strong>Ce que vous allez découvrir :</strong></p><p>Le modèle ne connaît pas l&#39;heure actuelle — c&#39;est un modèle de langage, pas une horloge. Mais avec l&#39;outil activé, il reconnaît que votre question correspond à la description de l&#39;outil et génère un appel structuré. L&#39;application exécute la function, obtient l&#39;heure réelle et la réinjecte. Le modèle intègre alors l&#39;heure réelle dans une réponse en langage naturel.</p><hr><h3 id="exercice-2-l-experience-de-la-description" tabindex="-1">Exercice 2 : L&#39;expérience de la description <a class="header-anchor" href="#exercice-2-l-experience-de-la-description" aria-label="Permalink to &quot;Exercice 2 : L&#39;expérience de la description&quot;">​</a></h3><p><strong>Ce qu&#39;il faut faire :</strong></p><ol><li>Dans le <strong>Tool Workshop</strong>, créez un nouvel outil personnalisé à partir de zéro : <ul><li><strong>Name</strong> : <code>weather_check</code></li><li><strong>Description</strong> : &quot;Get the current weather for a location&quot;</li><li><strong>Parameters</strong> : un paramètre requis <code>city</code> de type <code>string</code></li></ul></li><li>Utilisez le workflow <strong>Probe &amp; Pick</strong> pour tester le schema — vérifiez que l&#39;onglet Schema affiche le JSON Schema correct</li><li>Allez dans <strong>Chat</strong>, activez l&#39;outil dans les <strong>Chat Settings</strong>, et demandez : <em>&quot;What&#39;s the weather in Paris?&quot;</em></li><li>Le modèle devrait appeler <code>weather_check</code> avec <code>{&quot;city&quot;: &quot;Paris&quot;}</code></li><li>Retournez maintenant dans le <strong>Tool Workshop</strong> et modifiez la description pour quelque chose de vague : <strong>&quot;A function&quot;</strong></li><li>Retournez dans Chat (démarrez une nouvelle conversation) et posez la même question. Le modèle appelle-t-il toujours l&#39;outil ?</li><li>Modifiez la description une dernière fois — supprimez-la entièrement (laissez-la vide)</li><li>Demandez à nouveau. Que se passe-t-il ?</li></ol><p><strong>Ce que vous allez découvrir :</strong></p><p>Avec une description claire, le modèle fait correspondre votre requête à l&#39;outil de manière fiable. Avec une description vague, il peut encore appeler l&#39;outil (s&#39;il est le seul disponible) mais avec moins de confiance. Sans aucune description, le comportement devient imprévisible — certains modèles ignoreront l&#39;outil, d&#39;autres l&#39;appelleront au hasard. Cela prouve que la description n&#39;est pas de la métadonnée pour les humains — c&#39;est le signal principal que le modèle utilise pour déterminer la pertinence.</p><hr><h3 id="exercice-3-anatomie-d-un-appel-d-outil" tabindex="-1">Exercice 3 : Anatomie d&#39;un appel d&#39;outil <a class="header-anchor" href="#exercice-3-anatomie-d-un-appel-d-outil" aria-label="Permalink to &quot;Exercice 3 : Anatomie d&#39;un appel d&#39;outil&quot;">​</a></h3><p><strong>Ce qu&#39;il faut faire :</strong></p><ol><li>Après avoir terminé les Exercices 1 et 2, ouvrez la page <strong>Session</strong> et trouvez une conversation contenant des appels d&#39;outils</li><li>Ouvrez l&#39;onglet <strong>Tools</strong> pour voir le <strong>ToolCallTimeline</strong> — une vue chronologique de chaque invocation d&#39;outil dans la session</li><li>Cliquez sur un <strong>ToolCallCard</strong> pour le développer. Examinez : <ul><li><strong>Nom de la function</strong> — Quel outil le modèle a-t-il appelé ?</li><li><strong>Arguments</strong> — Quels arguments JSON le modèle a-t-il générés ? Sont-ils valides par rapport au schema ?</li><li><strong>Statut d&#39;exécution</strong> — L&#39;outil a-t-il réussi ou échoué ?</li><li><strong>Durée</strong> — Combien de temps l&#39;exécution a-t-elle pris (en millisecondes) ?</li><li><strong>Résultat</strong> — Quelles données sont revenues de l&#39;outil ?</li></ul></li><li>Lisez maintenant la réponse finale du modèle qui a suivi cet appel d&#39;outil</li><li>Comparez : la réponse en langage naturel du modèle était-elle fidèle au résultat de l&#39;outil ? A-t-il ajouté des informations qui n&#39;étaient pas dans le résultat ? A-t-il omis quelque chose ?</li></ol><p><strong>Ce que vous allez découvrir :</strong></p><p>Le ToolCallCard vous offre une transparence complète sur la boucle du tool calling. Vous pouvez voir exactement ce que le modèle a demandé, ce qu&#39;il a reçu et comment il a utilisé cette information. Parfois le modèle est parfaitement fidèle au résultat. D&#39;autres fois, il paraphrase, ajoute un langage de prudence (&quot;Based on the data...&quot;), ou complète même le résultat de l&#39;outil avec ses propres connaissances — qui peuvent ou non être exactes.</p><hr><h3 id="exercice-4-orchestration-multi-outils" tabindex="-1">Exercice 4 : Orchestration multi-outils <a class="header-anchor" href="#exercice-4-orchestration-multi-outils" aria-label="Permalink to &quot;Exercice 4 : Orchestration multi-outils&quot;">​</a></h3><p><strong>Ce qu&#39;il faut faire :</strong></p><ol><li>Activez <strong>3 outils ou plus</strong> dans les Chat Settings — par exemple : <strong>Current Time</strong>, <strong>Calculator</strong> et <strong>UUID Generator</strong></li><li>Posez une question composée qui nécessite les trois : <em>&quot;Generate a UUID, then tell me the current time, then calculate 42 * 17.&quot;</em></li><li>Observez attentivement la réponse du modèle : <ul><li>Appelle-t-il les trois outils ?</li><li>Les appelle-t-il dans l&#39;ordre que vous avez spécifié ?</li><li>Essaie-t-il de les appeler tous en même temps (parallèle) ou un par un (séquentiel) ?</li></ul></li><li>Consultez le <strong>ToolCallTimeline</strong> sur la page Session pour voir la séquence exacte et le timing</li><li>Essayez maintenant une requête plus ambiguë : <em>&quot;I need a unique identifier and some math — what&#39;s 256 divided by 8?&quot;</em><ul><li>Le modèle appelle-t-il le UUID generator même si vous avez dit &quot;unique identifier&quot; et non &quot;UUID&quot; ?</li><li>Utilise-t-il la calculatrice ou répond-il au calcul à partir de ses propres connaissances ?</li></ul></li></ol><p><strong>Ce que vous allez découvrir :</strong></p><p>L&#39;orchestration multi-outils révèle comment le modèle priorise et séquence les appels. Certains modèles appelleront tous les outils en parallèle ; d&#39;autres les enchaîneront séquentiellement. L&#39;ordre peut ne pas correspondre à votre requête — le modèle génère ce qu&#39;il prédit devoir venir ensuite, pas ce que vous avez demandé en premier. Un phrasé ambigu teste si le modèle peut faire correspondre un langage informel (&quot;unique identifier&quot;) à des noms d&#39;outils formels (<code>generate_uuid</code>). C&#39;est la correspondance de motifs en action — et elle ne correspond pas toujours de la manière attendue.</p><hr><h2 id="points-cles" tabindex="-1">Points Clés <a class="header-anchor" href="#points-cles" aria-label="Permalink to &quot;Points Clés&quot;">​</a></h2><ol><li><strong>Le tool calling est de la génération structurée, pas de l&#39;intelligence.</strong> Le modèle produit un objet JSON correspondant à un schema — il ne comprend pas ce que fait la function ni comment elle fonctionne.</li><li><strong>Le champ description est primordial.</strong> C&#39;est le seul signal que le modèle utilise pour décider quand et si appeler un outil. Des descriptions vagues mènent à un comportement peu fiable.</li><li><strong>Le modèle propose, l&#39;application dispose.</strong> Chaque appel d&#39;outil passe par du code applicatif qui peut le valider, l&#39;exécuter ou le rejeter. La sécurité repose sur cette séparation.</li><li><strong>L&#39;orchestration multi-outils dépend des motifs.</strong> Le modèle peut appeler les outils dans un ordre inattendu, en ignorer certains ou appeler le mauvais lorsque les descriptions se chevauchent. Testez minutieusement.</li><li><strong>Tous les modèles ne peuvent pas utiliser des outils.</strong> Le tool calling nécessite un affinage spécifique. LLMxRay détecte automatiquement le support pour que vous n&#39;ayez pas à deviner.</li></ol><hr><h2 id="questions-de-discussion" tabindex="-1">Questions de Discussion <a class="header-anchor" href="#questions-de-discussion" aria-label="Permalink to &quot;Questions de Discussion&quot;">​</a></h2><ol><li>Si le tool calling n&#39;est que de la correspondance de motifs, qu&#39;est-ce qui empêche le modèle d&#39;appeler un outil dangereux — par exemple, un outil qui supprime des fichiers ou envoie des e-mails ? Comment devrait-on concevoir les permissions d&#39;outils dans un système en production ?</li><li>Que se passe-t-il si un outil renvoie une erreur — le modèle la gère-t-il avec élégance ? L&#39;application devrait-elle masquer les erreurs au modèle ou les montrer ? Quels sont les compromis ?</li><li>Le modèle sélectionne les outils en se basant sur des descriptions rédigées par des humains. Que se passe-t-il si la description est trompeuse — intentionnellement ou accidentellement ? Cela pourrait-il être exploité ?</li><li>Certains systèmes de tool calling permettent au modèle d&#39;écrire du code arbitraire (comme un outil interpréteur Python). Cela franchit-il la ligne entre &quot;sortie structurée&quot; et &quot;agentivité&quot; ? Où devrait se situer la frontière ?</li><li>Si deux outils ont des descriptions qui se chevauchent (par ex. &quot;search the web&quot; et &quot;look up information online&quot;), comment le modèle choisit-il entre eux ? Qu&#39;est-ce que cela nous apprend sur les limites du routage basé sur les descriptions ?</li></ol><hr><h2 id="lectures-complementaires" tabindex="-1">Lectures Complémentaires <a class="header-anchor" href="#lectures-complementaires" aria-label="Permalink to &quot;Lectures Complémentaires&quot;">​</a></h2><h3 id="articles-academiques" tabindex="-1">Articles académiques <a class="header-anchor" href="#articles-academiques" aria-label="Permalink to &quot;Articles académiques&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Article</th><th>Auteurs</th><th>Année</th><th>Lien</th></tr></thead><tbody><tr><td>Toolformer: Language Models Can Teach Themselves to Use Tools</td><td>Schick et al.</td><td>2023</td><td><a href="https://arxiv.org/abs/2302.04761" target="_blank" rel="noreferrer">arXiv:2302.04761</a></td></tr><tr><td>Gorilla: Large Language Model Connected with Massive APIs</td><td>Patil et al.</td><td>2023</td><td><a href="https://arxiv.org/abs/2305.15334" target="_blank" rel="noreferrer">arXiv:2305.15334</a></td></tr><tr><td>ToolBench: An Open Platform for Training, Serving, and Evaluating LLM Tool Learning</td><td>Qin et al.</td><td>2023</td><td><a href="https://arxiv.org/abs/2305.16504" target="_blank" rel="noreferrer">arXiv:2305.16504</a></td></tr><tr><td>Function Calling and Tool Use</td><td>OpenAI</td><td>2023</td><td><a href="https://platform.openai.com/docs/guides/function-calling" target="_blank" rel="noreferrer">platform.openai.com/docs</a></td></tr></tbody></table><h3 id="tutoriels-et-explications" tabindex="-1">Tutoriels et explications <a class="header-anchor" href="#tutoriels-et-explications" aria-label="Permalink to &quot;Tutoriels et explications&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Ressource</th><th>Auteur</th><th>Lien</th></tr></thead><tbody><tr><td>Ollama Tool Calling Documentation</td><td>Ollama</td><td><a href="https://ollama.com/blog/tool-support" target="_blank" rel="noreferrer">ollama.com/blog/tool-support</a></td></tr><tr><td>LLMxRay Tool Workshop Guide</td><td>LLMxRay Docs</td><td><a href="/llmxray/docs/fr/guide/tool-workshop.html">Tool Workshop</a></td></tr></tbody></table><hr><h2 id="evaluation" tabindex="-1">Évaluation <a class="header-anchor" href="#evaluation" aria-label="Permalink to &quot;Évaluation&quot;">​</a></h2><p><strong>Option A — Démonstration en direct + revue de code (individuel) :</strong> Construisez un outil personnalisé dans le Tool Workshop à partir de zéro (pas à partir d&#39;un modèle). Lors d&#39;une démonstration en direct, montrez : la définition de l&#39;outil avec une description et des paramètres bien élaborés, le code d&#39;implémentation, le schema auto-généré et une session de chat en direct où le modèle appelle votre outil. Expliquez chaque étape de la boucle du tool calling au fur et à mesure. Soyez prêt à répondre à : &quot;Que se passerait-il si vous changiez la description ?&quot;</p><p><strong>Option B — Test de résistance des descriptions (en binôme) :</strong> Créez un outil unique et testez-le avec 5 descriptions progressivement dégradées : (1) précise et détaillée, (2) correcte mais brève, (3) vague, (4) trompeuse, (5) vide. Pour chaque version, exécutez 3 prompts de chat et notez si le modèle a appelé l&#39;outil correctement. Présentez vos résultats sous forme de tableau avec les taux de réussite et une courte analyse du seuil à partir duquel les descriptions deviennent trop pauvres pour être utiles.</p><p><strong>Option C — Défi de conception multi-outils (groupes de 3-4) :</strong> Concevez un ensemble de 4 outils qui fonctionnent ensemble pour résoudre une tâche réaliste (par ex. un planificateur de voyage : consultation météo, convertisseur de devises, convertisseur de fuseaux horaires, calculateur de distances). Rédigez les définitions d&#39;outils avec descriptions et schemas. Testez-les dans LLMxRay avec des requêtes composées. Présentez : vos définitions d&#39;outils, une transcription du modèle orchestrant les quatre outils et une analyse de ce qui a fonctionné et de ce qui a échoué.</p><hr><h2 id="la-suite" tabindex="-1">La Suite <a class="header-anchor" href="#la-suite" aria-label="Permalink to &quot;La Suite&quot;">​</a></h2><p>Dans le <strong><a href="./module-7.html">Module 7 : Comment comparer les modèles ?</a></strong>, vous passerez de l&#39;observation d&#39;un seul modèle à la comparaison de plusieurs modèles côte à côte. Vous découvrirez qu&#39;un modèle obtenant 90 % sur un benchmark et 40 % sur un autre n&#39;est pas défaillant — cela reflète les motifs spécifiques qu&#39;il a appris durant l&#39;entraînement. Le benchmarking est la méthode qui rend les différences entre modèles mesurables, reproductibles et honnêtes.</p><hr><div style="background:rgba(168,85,247,0.06);border-radius:8px;padding:1rem 1.5rem;margin-top:2rem;font-size:0.9rem;color:var(--vp-c-text-2);"><p><strong>Module 6 sur 8</strong> du Kit Enseignants LLMxRay <a href="./module-5.html">← Module 5 : Quand le modèle oublie-t-il ?</a> | <a href="./index.html">Retour au programme</a> | <a href="./module-7.html">Module 7 : Comment comparer les modèles ? →</a></p></div>',84)])])}const k=t(r,[["render",u]]);export{q as __pageData,k as default};
